+/** Sort keys the catalogue API accepts, mapped to the real (whitelisted) columns. */
+const sortColumns = {
+  name: 'name',
+  price: 'price_cents',
+  stock: 'stock',
+} as const;
+
+export type ProductSort = keyof typeof sortColumns;
+
+function isProductSort(value: string): value is ProductSort {
+  return Object.hasOwn(sortColumns, value);
+}
+
+/** Lists the catalogue ordered by `sort` (name by default). Unknown keys fall back to name. */
+export async function listProducts(db: Queryable, sort = 'name'): Promise<Product[]> {
+  const column = isProductSort(sort) ? sortColumns[sort] : sortColumns.name;
+  const { rows } = await db.query<Product>(`select ${columns} from products order by ${column}`);
   return rows;
 }

